'use client';
// Tools-only component consumer, never included in project-template or production app routes.
import {useState,useCallback,useRef} from 'react';import CopyButton from '../components/elements/copy-button';
export default function Page(){const [alternate,setAlternate]=useState(false),[submits,setSubmits]=useState(0),[rows,setRows]=useState(0),pending=useRef<{resolve:()=>void;reject:(e:Error)=>void}|null>(null);const write=useCallback(()=>new Promise<void>((resolve,reject)=>pending.current={resolve,reject}),[]);return <main style={{padding:24}}><h1>Reviewed copy messages</h1><output aria-label="form submits">{submits}</output><output aria-label="row clicks">{rows}</output><form onSubmit={event=>{event.preventDefault();setSubmits(v=>v+1);}}><div onClick={()=>setRows(v=>v+1)}><CopyButton value="SYNTHETIC_REVIEW_VALUE" label="Localized copy" write={write} messages={alternate?{action:'Copy item',pending:'Copying item',succeeded:'<b>Item copied</b>',retry:'Retry item',denied:'Item permission denied'}:{action:'Copy reference',pending:'Copying reference',succeeded:'Reference copied',retry:'Retry reference',denied:'Reference permission denied'}}/></div></form><CopyButton value="Default sample" label="Default copy" write={async()=>{}}/><CopyButton value="" label="Empty copy" messages={{empty:'No reference available'}}/><button type="button" onClick={()=>setAlternate(v=>!v)}>Change text</button><button type="button" onClick={()=>pending.current?.resolve()}>Resolve copy</button><button type="button" onClick={()=>pending.current?.reject(new DOMException('Private synthetic failure','NotAllowedError'))}>Deny copy</button><button type="button" onClick={()=>window.dispatchEvent(new Event('templux:session-ending'))}>End session</button></main>;}
